def coefficient_de_temps(apps, schema_editor):
    """Coefficient de temps calé sur la pièce test du 14/10/2026, sur les paramètres de jet d'eau dont le coefficient
    d'ajustement n'a pas été modifié (1)."""
    from decoupe.services.vitesses import coefficient_temps

    for parametre in apps.get_model("decoupe", "ParametreCoupe").objects.filter(procede="jet_eau", coefficient_ajustement=1):
        parametre.coefficient_ajustement = coefficient_temps(parametre.epaisseur_mm)
        parametre.save(update_fields=["coefficient_ajustement"])


def creer_acier_trempe(apps, schema_editor):
    """XC70 = acier trempé : ses paramètres de jet d'eau reprennent ceux de l'acier (perçage, paliers…) avec l'usinabilité
    calée sur la pièce test. Les épaisseurs déjà présentes ne sont pas touchées."""
    from decoupe.services.vitesses import USINABILITE_XC70, coefficient_temps, vitesses_depuis_usinabilite

    Parametre, Vitesse = apps.get_model("decoupe", "ParametreCoupe"), apps.get_model("decoupe", "VitesseCoupe")
    Famille = apps.get_model("technique", "FamilleMatiere")
    acier, trempe = Famille.objects.filter(nom__iexact="Acier").first(), Famille.objects.filter(nom__iexact="Acier trempé").first()
    if acier is None or trempe is None:
        return
    for modele in Parametre.objects.filter(procede="jet_eau", famille=acier):
        if Parametre.objects.filter(procede="jet_eau", famille=trempe, epaisseur_mm=modele.epaisseur_mm).exists():
            continue
        vitesses = list(modele.vitesses.all())
        modele.pk, modele.famille_id, modele.usinabilite, modele.origine = None, trempe.pk, USINABILITE_XC70, "calcule"
        modele.coefficient_ajustement = coefficient_temps(modele.epaisseur_mm)
        modele.save()
        calculees = {c["qualite"]: c for c in vitesses_depuis_usinabilite(USINABILITE_XC70, modele.epaisseur_mm)}
        for v in vitesses:
            calcule = calculees.get(float(v.qualite))
            if calcule:
                v.pk, v.parametre_id = None, modele.pk
                v.vitesse_haute_mm_min, v.vitesse_basse_mm_min = calcule["vitesse_haute_mm_min"], calcule["vitesse_basse_mm_min"]
                v.save()


